	(5, NULL, 890, 3240, 1680, 2600, 990, 2, 6, 5, 0, 5, 2, 0, 2, 3, 3, 0, 0, 0.80, 3060100000005, 0, 3500, 'Hình như ta sống trên ngàn năm rồi thì phải.|Lúc đầu nên đi làm nhiệm vụ để nhanh lên cấp.|Mỗi ngày vào game sẽ nhận quà miễn phí và mua được vật phẩm giảm giá.', 'Lão Cổ Thụ', 2, 5, 2, 2, 2, 2, 0, 2, 1, 2060100000005, NULL, -1, NULL, 10),
